## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/febrilInfantLogic.ts`

```typescript
/**
 * Febrile Infant Evaluation Clinical Compass™
 * Logic Engine — AAP Clinical Practice Guideline 2021 (updated 2025)
 *
 * References:
 * 1. Pantell RH et al. Evaluation and Management of Well-Appearing Febrile Infants
 *    8 to 60 Days Old. Pediatrics. 2021;148(2):e2021052228. (AAP CPG)
 * 2. AAP Section on Emergency Medicine. Febrile Infant Management Update. Pediatrics. 2025.
 * 3. Kuppermann N et al. A Clinical Prediction Rule to Identify Febrile Infants at
 *    Low Risk for Serious Bacterial Infection. JAMA. 2019;322(18):1765–1776. (PECARN)
 */

export type InfantAgeGroup =
  | "0_7_days"    // neonates — always admit
  | "8_21_days"   // high risk — full sepsis workup + admit
  | "22_28_days"  // high risk — full workup + admit
  | "29_60_days"; // risk stratification possible

export interface FebrilInfantInput {
  ageGroup: InfantAgeGroup;
  ageDays: number;
  temperatureCelsius: number;
  wellAppearing: boolean; // Yale Observation Scale / clinical gestalt
  pretermBirth: boolean;
  gestationalAgeWeeks: number;
  priorAntibiotics: boolean;
  priorHospitalization: boolean;
  immunocompromised: boolean;
  // Lab values
  wbcCount: number | null; // cells/μL
  absoluteNeutrophilCount: number | null; // ANC cells/μL
  bandCount: number | null; // %
  cReactiveProtein: number | null; // mg/L
  procalcitonin: number | null; // ng/mL
  urinalysisPositive: boolean | null; // positive if ≥5 WBC/hpf or positive leukocyte esterase
  csfWBC: number | null; // cells/μL
  csfProtein: number | null; // mg/dL
  csfGlucose: number | null; // mg/dL
  // Clinical context
  sourceFocusFound: boolean; // e.g., otitis media
  hsvRiskFactors: boolean; // maternal HSV, skin/eye/mouth lesions, seizures
  hasSeizures: boolean;
  hasSkinLesions: boolean;
  hasEyeDischarge: boolean;
  // PECARN criteria (29–60 days)
  pecarnLowRisk: boolean | null; // null if not calculated
}

export interface FebrilInfantRecommendation {
  primaryRecommendation: string;
  riskCategory: "low" | "intermediate" | "high" | "very_high";
  workupRequired: string[];
  admissionDecision: string;
  antibioticRecommendation: string;
  hsvManagement: string;
  urgentFlags: string[];
  dispositionPlan: string;
  followUpPlan: string;
  evidenceLevel: "A" | "B" | "C";
  rationale: string;
  references: Array<{ citation: string; url: string }>;
}

export function assessFebrilInfant(
  input: FebrilInfantInput
): FebrilInfantRecommendation {
  const urgentFlags: string[] = [];
  const workup: string[] = [];

  // ─── HSV risk ─────────────────────────────────────────────────────────────
  if (input.hsvRiskFactors || input.hasSeizures || input.hasSkinLesions || input.hasEyeDischarge) {
    urgentFlags.push("HSV RISK: Obtain HSV PCR (blood + CSF + surface swabs). Initiate acyclovir 20mg/kg IV q8h empirically. Do NOT delay treatment pending results.");
  }

  // ─── Age 0–7 days ─────────────────────────────────────────────────────────
  if (input.ageGroup === "0_7_days") {
    urgentFlags.push("NEONATE (0–7 days): Full sepsis evaluation + empiric antibiotics + ADMISSION required regardless of appearance.");
    workup.push("CBC with differential", "Blood culture × 2", "Urinalysis + urine culture (catheterized)", "Lumbar puncture (CSF cell count, protein, glucose, culture, HSV PCR)", "CRP and procalcitonin", "Chest X-ray if respiratory symptoms", "HSV surface swabs (eye, nasopharynx, rectum)");
    return {
      primaryRecommendation: "NEONATE FEVER (0–7 days): ADMIT + FULL SEPSIS WORKUP + EMPIRIC ANTIBIOTICS. Ampicillin + gentamicin ± cefotaxime. Add acyclovir if HSV risk.",
      riskCategory: "very_high",
      workupRequired: workup,
      admissionDecision: "ADMIT to NICU or inpatient pediatrics. Full sepsis evaluation mandatory.",
      antibioticRecommendation: "Ampicillin 50mg/kg IV q6h + Gentamicin 4mg/kg IV q24h. Add cefotaxime 50mg/kg IV q6h if meningitis suspected. Acyclovir 20mg/kg IV q8h if HSV risk.",
      hsvManagement: "HSV surface swabs + HSV PCR (blood + CSF). Empiric acyclovir 20mg/kg IV q8h until HSV excluded.",
      urgentFlags,
      dispositionPlan: "ADMIT to NICU or inpatient pediatrics. Minimum 48-hour observation pending cultures.",
      followUpPlan: "Cultures at 24–48 hours. Adjust antibiotics per sensitivities. Repeat LP if initial CSF traumatic.",
      evidenceLevel: "A",
      rationale: `Neonate ${input.ageDays} days. Temperature ${input.temperatureCelsius}°C. Full workup mandatory per AAP 2021 CPG.`,
      references: [
        { citation: "Pantell RH et al. Evaluation and Management of Well-Appearing Febrile Infants 8 to 60 Days Old. Pediatrics. 2021;148(2):e2021052228.", url: "https://publications.aap.org/pediatrics/article/148/2/e2021052228" },
      ],
    };
  }

  // ─── Age 8–28 days ────────────────────────────────────────────────────────
  if (input.ageGroup === "8_21_days" || input.ageGroup === "22_28_days") {
    urgentFlags.push(`HIGH-RISK AGE GROUP (${input.ageDays} days): Full sepsis evaluation + empiric antibiotics + ADMISSION strongly recommended.`);
    workup.push("CBC with differential + ANC", "Blood culture", "Urinalysis + urine culture (catheterized)", "Lumbar puncture (CSF analysis + culture + HSV PCR)", "CRP and procalcitonin", "Chest X-ray if respiratory symptoms");
    return {
      primaryRecommendation: `FEBRILE INFANT ${input.ageDays} DAYS: ADMIT + FULL WORKUP + EMPIRIC ANTIBIOTICS. Risk stratification possible at 22–28 days but admission still preferred.`,
      riskCategory: "high",
      workupRequired: workup,
      admissionDecision: "ADMIT. Empiric antibiotics after cultures obtained. LP should not be deferred.",
      antibioticRecommendation: "Ampicillin 50mg/kg IV q6h + Cefotaxime 50mg/kg IV q6h (or gentamicin if cefotaxime unavailable). Acyclovir 20mg/kg IV q8h if HSV risk.",
      hsvManagement: input.hsvRiskFactors || input.hasSeizures || input.hasSkinLesions
        ? "HSV RISK PRESENT: Acyclovir 20mg/kg IV q8h empirically. HSV PCR blood + CSF + surface swabs."
        : "Low HSV risk. Obtain HSV PCR from CSF at time of LP. Acyclovir not required unless risk factors present.",
      urgentFlags,
      dispositionPlan: "ADMIT to inpatient pediatrics. 48-hour observation minimum.",
      followUpPlan: "Blood and urine cultures at 24–48 hours. Adjust antibiotics per sensitivities. Discontinue antibiotics if cultures negative and well-appearing at 48 hours.",
      evidenceLevel: "A",
      rationale: `Age ${input.ageDays} days. Temperature ${input.temperatureCelsius}°C. Well-appearing: ${input.wellAppearing}. Per AAP 2021 CPG.`,
      references: [
        { citation: "Pantell RH et al. Evaluation and Management of Well-Appearing Febrile Infants 8 to 60 Days Old. Pediatrics. 2021;148(2):e2021052228.", url: "https://publications.aap.org/pediatrics/article/148/2/e2021052228" },
      ],
    };
  }

  // ─── Age 29–60 days — PECARN/AAP risk stratification ─────────────────────
  workup.push("Urinalysis + urine culture (catheterized) — MANDATORY", "CBC with differential", "Blood culture", "CRP and/or procalcitonin");

  // Determine risk category
  let riskCategory: "low" | "intermediate" | "high" = "intermediate";
  let admissionDecision: string;
  let antibioticRec: string;
  let dispositionPlan: string;

  const ancLow = input.absoluteNeutrophilCount !== null && input.absoluteNeutrophilCount < 4090;
  const procalLow = input.procalcitonin !== null && input.procalcitonin < 0.5;
  const crpLow = input.cReactiveProtein !== null && input.cReactiveProtein < 20;
  const uaPositive = input.urinalysisPositive === true;

  if (!input.wellAppearing) {
    riskCategory = "high";
    urgentFlags.push("ILL-APPEARING INFANT: Full sepsis workup + empiric antibiotics + ADMISSION regardless of lab values.");
    admissionDecision = "ADMIT. Ill-appearing infant — full workup mandatory.";
    antibioticRec = "Ceftriaxone 50mg/kg IV/IM q24h (or ampicillin + cefotaxime). Add acyclovir if HSV risk.";
    dispositionPlan = "ADMIT to inpatient pediatrics.";
    workup.push("Lumbar puncture (CSF analysis + culture + HSV PCR)");
  } else if (input.pecarnLowRisk === true && !uaPositive && ancLow && procalLow) {
    riskCategory = "low";
    admissionDecision = "LOW RISK: Outpatient management acceptable IF reliable follow-up within 24 hours AND urine culture pending. No LP required per PECARN criteria.";
    antibioticRec = "Antibiotics NOT required if low risk and well-appearing. If empiric treatment chosen: ceftriaxone 50mg/kg IM single dose with 24-hour follow-up.";
    dispositionPlan = "DISCHARGE with strict return precautions. Follow-up in 24 hours. Urine culture must be followed.";
  } else if (uaPositive && !ancLow) {
    riskCategory = "intermediate";
    admissionDecision = "INTERMEDIATE RISK: LP recommended. Admit vs. discharge with empiric antibiotics based on clinical judgment and family reliability.";
    antibioticRec = "Ceftriaxone 50mg/kg IV/IM. If UTI source: continue ceftriaxone pending culture. LP recommended before antibiotics if meningitis not excluded.";
    dispositionPlan = "Admit for observation OR discharge with empiric ceftriaxone + 24-hour follow-up if LP negative and reliable family.";
    workup.push("Lumbar puncture recommended (AAP 2021 — intermediate risk)");
  } else {
    riskCategory = "intermediate";
    admissionDecision = "INTERMEDIATE RISK: Clinical judgment required. LP recommended. Admit vs. discharge per clinical assessment.";
    antibioticRec = "Ceftriaxone 50mg/kg IV/IM after LP. Adjust per culture results.";
    dispositionPlan = "Admit for observation OR discharge with empiric ceftriaxone + 24-hour follow-up.";
    workup.push("Lumbar puncture recommended");
  }

  const hsvManagement = input.hsvRiskFactors || input.hasSeizures || input.hasSkinLesions || input.hasEyeDischarge
    ? "HSV RISK PRESENT: Acyclovir 20mg/kg IV q8h empirically. HSV PCR (blood + CSF + surface swabs). Ophthalmology consult for eye lesions."
    : "Low HSV risk at 29–60 days. Acyclovir not routinely indicated unless risk factors present.";

  const primaryRec = urgentFlags.length > 0
    ? urgentFlags[0]
    : `FEBRILE INFANT ${input.ageDays} DAYS — ${riskCategory.toUpperCase()} RISK. Temperature ${input.temperatureCelsius}°C. ${admissionDecision.split(":")[0]}.`;

  return {
    primaryRecommendation: primaryRec,
    riskCategory,
    workupRequired: workup,
    admissionDecision,
    antibioticRecommendation: antibioticRec,
    hsvManagement,
    urgentFlags,
    dispositionPlan,
    followUpPlan: riskCategory === "low"
      ? "Mandatory 24-hour follow-up. Return immediately for fever recurrence, ill appearance, or positive culture result."
      : "Follow-up per inpatient course. Cultures at 24–48 hours. Adjust antibiotics per sensitivities.",
    evidenceLevel: "A",
    rationale: `Age ${input.ageDays} days. Temp ${input.temperatureCelsius}°C. Well-appearing: ${input.wellAppearing}. ANC: ${input.absoluteNeutrophilCount ?? "not obtained"}. PCT: ${input.procalcitonin ?? "not obtained"}. UA positive: ${input.urinalysisPositive}. PECARN low risk: ${input.pecarnLowRisk}. Per AAP 2021 CPG and PECARN 2019.`,
    references: [
      { citation: "Pantell RH et al. Evaluation and Management of Well-Appearing Febrile Infants 8 to 60 Days Old. Pediatrics. 2021;148(2):e2021052228.", url: "https://publications.aap.org/pediatrics/article/148/2/e2021052228" },
      { citation: "Kuppermann N et al. A Clinical Prediction Rule to Identify Febrile Infants at Low Risk for Serious Bacterial Infection. JAMA. 2019;322(18):1765–1776. (PECARN)", url: "https://jamanetwork.com/journals/jama/fullarticle/2755184" },
    ],
  };
}
